customer_signups_and_transactions = GRAPH.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_period) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS("-", YEAR(join_date), LPAD(MONTH(join_date), 2, "0"))
).PARTITION(name="monthly_signups", by=(signup_month)).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF("seconds", join_date, MIN(transactions_made.date_time)) / 86400
)

result = Cars.WHERE(LOWER(make) == LOWER('Toyota')).sale_records.WHERE(
    DATEDIFF("days", sale_date, DATETIME('now')) <= 30
).CALCULATE(
    number_of_sales=COUNT(Sales),
    total_revenue=SUM(sale_price)
).SINGULAR()

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

avg_payment_days_per_sale = Sales.WHERE(HAS(payment) == 1).CALCULATE(
    sale_id=_id,
    avg_days_to_payment=ROUND(
        AVG(
            payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') <= 7))
)

result = Merchants.CALCULATE(
    merchant_name=name,
    cpur=NDISTINCT(transactions_received.WHERE(
        (LOWER(status) == "success") & (coupon_id != None)
    ).coupon_id) / NDISTINCT(transactions_received.WHERE(
        LOWER(status) == "success"
    ).txid)
)

result = Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
    DATEDIFF("days", created_at, DATETIME('now')) <= 7
).CALCULATE(
    num_transactions=COUNT(Transactions),
    total_amount=SUM(amount)
).SINGULAR()

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_duration = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    )
).ORDER_BY(total_duration.DESC())

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", user.created_at, created_at) <= 365
        )
    ) == 1
).CALCULATE(
    user_name=username,
    user_email=email,
    signup_date=created_at
)

users_without_first_year_notification = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", created_at, notifications.created_at) <= 365
        )
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
